124:reg     [15:0]  shb_output;
135:        WRBUS_SOURCE_SHB     : reg_wrbus = shb_output;
263:reg             reg_ovm = 1'b0; //0 = overflow disabled, 1 = overflow enabled 
264:reg             reg_ovm_set, reg_ovm_rst;
266:    case({reg_ovm_set, reg_ovm_rst})
267:        2'b01: reg_ovm <= 1'b0;
268:        2'b10: reg_ovm <= 1'b1;
269:        default: reg_ovm <= reg_ovm;
426:reg     [4:0]   sha_amt; //ALU input shifter control
430:    sha_output = sha_output << sha_amt; //do arithmetic shift
434:reg     [3:0]   alu_modesel; //000 AND, 001 OR,  010 XOR, 011 ABS
448:IKA32010_alu u_alu (
450:    .i_ALU_OVM(reg_ovm), .i_ALU_MODESEL(alu_modesel), .i_ALU_PAZ(alu_paz), .i_ALU_PBZ(alu_pbz), .i_ALU_PBDATA(alu_pbdata),
459:reg             shb_mux;
460:reg     [2:0]   shb_amt; //ALU output shifter control
462:reg     [31:0]  shb_intermediate;
463:assign          shb_output = shb_mux ? shb_intermediate[31:16] : shb_intermediate[15:0];
465:    case(shb_amt)
466:        3'd0:    shb_intermediate = alu_acc_output;
467:        3'd1:    shb_intermediate = alu_acc_output << 1;
468:        3'd4:    shb_intermediate = alu_acc_output << 4;
469:        default: shb_intermediate = alu_acc_output;
479:assign  flag_output = {alu_flag_ovfl, reg_ovm, reg_intm, 4'b1111, reg_arp, 6'b111111, 1'b1, reg_dp}; //bit1 is don't care
552:    alu_modesel = ALU_ADD; alu_paz = NO; alu_pbz = NO; alu_pbdata = ALU_PBDATA_LONGWORD; alu_pbsel = ALU_SOURCE_SHFT;
561:    reg_ovm_set = NO; reg_ovm_rst = NO;
584:    sha_amt = 5'd0;
586:    shb_amt = 3'd0;
587:    shb_mux = LOW;
667:                if(reg_wrbus[14]) reg_ovm_set = YES; //overflow mode bit
668:                else              reg_ovm_rst = YES;
696:                    alu_modesel = ALU_ADD; alu_paz = YES; alu_pbdata = ALU_PBDATA_LOWWORD; //load from port B
736:                reg_ovm_rst = YES;
745:                reg_ovm_set = YES;
777:                alu_modesel = ALU_ABS; alu_pbz = YES; //disable port B
787:                alu_modesel = ALU_ADD; //load from port B
789:                sha_amt = {1'b0, if_opcodereg[11:8]};
806:                alu_modesel = ALU_ADD; alu_pbdata = ALU_PBDATA_LONGWORD; //load from port B, low bits masked
808:                sha_amt = 5'd16;
825:                alu_modesel = ALU_ADD; alu_pbdata = ALU_PBDATA_LONGWORD; //load from port B
844:                alu_modesel = ALU_AND; alu_pbdata = ALU_PBDATA_LOWWORD; //load from port B
862:                alu_modesel = ALU_ADD; alu_paz = YES; //block acc feedback
864:                sha_amt = {1'b0, if_opcodereg[11:8]};
881:                alu_modesel = ALU_ADD; alu_paz = YES; alu_pbdata = ALU_PBDATA_BYTE; //block acc feedback
892:                alu_modesel = ALU_OR; alu_pbdata = ALU_PBDATA_LOWWORD; //load from port B
912:                shb_amt = if_opcodereg[10:8]; shb_mux = HIGH;
931:                shb_mux = LOW;
948:                alu_modesel = ALU_SUB; //load from port B
950:                sha_amt = {1'b0, if_opcodereg[11:8]};
968:                alu_modesel = ALU_SUBC;
969:                sha_amt = 5'd15;
986:                alu_modesel = ALU_SUB; alu_pbdata = ALU_PBDATA_LONGWORD; //load from port B, low bits masked
988:                sha_amt = 5'd16;
1005:                alu_modesel = ALU_SUB; alu_pbdata = ALU_PBDATA_LONGWORD; //load from port B
1024:                alu_modesel = ALU_XOR; alu_pbdata = ALU_PBDATA_LOWWORD; //load from port B
1041:                alu_modesel = ALU_ADD; alu_paz = YES; alu_pbz = YES; //load from port B
1051:                alu_modesel = ALU_ADD; alu_paz = YES; alu_pbdata = ALU_PBDATA_HIGHWORD;
1053:                sha_amt = 5'd16;
1070:                alu_modesel = ALU_ADD; alu_paz = YES; alu_pbdata = ALU_PBDATA_LOWWORD;
1406:                    register_wrbus_source_sel = WRBUS_SOURCE_SHB; shb_mux = LOW;//PC write source is SHB
1470:                alu_pbsel = ALU_SOURCE_MUL; alu_modesel = ALU_ADD;
1497:                alu_pbsel = ALU_SOURCE_MUL; alu_modesel = ALU_ADD;
1516:                alu_pbsel = ALU_SOURCE_MUL; alu_modesel = ALU_ADD;
1563:                alu_pbsel = ALU_SOURCE_MUL; alu_modesel = ALU_ADD; alu_paz = YES; //block acc feedback
1573:                alu_pbsel = ALU_SOURCE_MUL; alu_modesel = ALU_SUB;
1760:module IKA32010_alu (
1793://subc related
1794:reg             prev_subc, subc_divided;
1799:reg             adder_cin;
1802:    adder_cin = 1'b0; //default carry
1803:    if(subc_divided) adder_cin = 1'b1; //add carry if divided
1805:        if(i_ALU_MODESEL == ALU_SUB || i_ALU_MODESEL == ALU_SUBC) adder_cin = 1'b1; //make 2's complement
1806:        else if(i_ALU_MODESEL == ALU_ABS) adder_cin = i_ALU_PA[31]; //make 2's complement if the ACC is negative, to take abs value
1810:    if(prev_subc) port_a = subc_divided ? 32'h0000_0000 : i_ALU_PA << 1;
1820:    if(prev_subc) port_b = subc_divided ? prev_adder << 1 : 32'h0000_0000;
1840:wire    [31:0]  alu_adder31 = port_a[30:0] + port_b[30:0] + adder_cin;
1850:    if(prev_subc) alu_output = port_a + port_b + adder_cin;
1867:    if(i_ALU_MODESEL == ALU_SUBC && alu_output[31] == 1'b0) subc_divided <= 1'b1;
1868:    else subc_divided <= 1'b0;
1870:    prev_subc <= i_ALU_MODESEL == ALU_SUBC;
1875:wire            alu_acc_ld = prev_subc | i_ALU_ACC_LD;

